import{_ as r,o as e,c as a,a2 as d}from"./chunks/framework.C7GIOALF.js";const g=JSON.parse('{"title":"Places and Everyday Activities Beyond Marvel","description":"","frontmatter":{},"headers":[],"relativePath":"research/everyday-life/places-and-activities.md","filePath":"research/everyday-life/places-and-activities.md","lastUpdated":null}'),n={name:"research/everyday-life/places-and-activities.md"};function i(o,t,s,c,l,h){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="places-and-everyday-activities-beyond-marvel" tabindex="-1">Places and Everyday Activities Beyond Marvel <a class="header-anchor" href="#places-and-everyday-activities-beyond-marvel" aria-label="Permalink to &quot;Places and Everyday Activities Beyond Marvel&quot;">​</a></h1><p>Streets, businesses, homes, work, meals, school, social events, and ordinary crime, checked October 19, 2026. This page includes instants, sorceries, enchantments, and lands. A theme about everyday life needs things for its people to do, not only creatures to attack with.</p><p><strong>Direct</strong> entries have a strong ordinary-life premise. <strong>Setting</strong> entries require a visual or era stretch. Supernatural Rooms, magical cooking, and other explicit exceptions appear under <a href="./almost-matches.html#places-and-activities">Almost matches</a>. <strong>Rent Is Due</strong> and <strong>School Daze</strong> are on the <a href="./marvel.html#everyday-activities">Marvel page</a>.</p><p><a href="./../everyday-life.html">Back to the full catalogue</a>.</p><h2 id="places" tabindex="-1">Places <a class="header-anchor" href="#places" aria-label="Permalink to &quot;Places&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Card and printing</th><th>Actual type</th><th>Fit</th><th>Why consider it / qualification</th></tr></thead><tbody><tr><td><a href="https://scryfall.com/card/fin/271/adventurers-inn" target="_blank" rel="noreferrer">Adventurer&#39;s Inn</a> · FIN 271</td><td>Land — Town</td><td>Setting</td><td>An ordinary lodging business for fantasy adventurers.</td></tr><tr><td><a href="https://scryfall.com/card/tmc/42/big-apple-3-am" target="_blank" rel="noreferrer">Big Apple, 3 a.m.</a> · TMC 42</td><td>Land</td><td>Direct</td><td>New York at night, with an ability that creates Rat tokens. One of the strongest cross-franchise lands.</td></tr><tr><td><a href="https://scryfall.com/card/snc/247/botanical-plaza" target="_blank" rel="noreferrer">Botanical Plaza</a> · SNC 247</td><td>Land</td><td>Setting</td><td>A city garden/plaza, with a fantasy Art Deco visual setting.</td></tr><tr><td><a href="https://scryfall.com/card/eoc/151/cabaretti-courtyard" target="_blank" rel="noreferrer">Cabaretti Courtyard</a> · EOC 151</td><td>Land</td><td>Setting</td><td>A social courtyard associated with a fantasy-city crime family.</td></tr><tr><td><a href="https://scryfall.com/card/otj/268/concealed-courtyard" target="_blank" rel="noreferrer">Concealed Courtyard</a> · OTJ 268</td><td>Land</td><td>Setting</td><td>A private urban courtyard, with a world-specific visual style.</td></tr><tr><td><a href="https://scryfall.com/card/fdn/687/demolition-field" target="_blank" rel="noreferrer">Demolition Field</a> · FDN 687</td><td>Land</td><td>Setting</td><td>A site being torn down; potential urban-redevelopment flavor depending on the printing.</td></tr><tr><td><a href="https://scryfall.com/card/tmt/186/illegitimate-business" target="_blank" rel="noreferrer">Illegitimate Business</a> · TMT 186</td><td>Land</td><td>Direct</td><td>An ordinary-looking city business with a criminal secret, from TMNT.</td></tr><tr><td><a href="https://scryfall.com/card/tla/270/jasmine-dragon-tea-shop" target="_blank" rel="noreferrer">Jasmine Dragon Tea Shop</a> · TLA 270</td><td>Land</td><td>Setting</td><td>An ordinary tea shop from Avatar. A strong service-business crossover, with a different city and era.</td></tr><tr><td><a href="https://scryfall.com/card/arn/76/library-of-alexandria" target="_blank" rel="noreferrer">Library of Alexandria</a> · ARN 76</td><td>Land</td><td>Setting</td><td>A real historical kind of institution, not modern New York. No need to chase a costly printing for the theme.</td></tr><tr><td><a href="https://scryfall.com/card/mkm/263/lush-portico" target="_blank" rel="noreferrer">Lush Portico</a> · MKM 263</td><td>Land — Forest Plains</td><td>Setting</td><td>An ordinary architectural feature within a fantasy setting.</td></tr><tr><td><a href="https://scryfall.com/card/eoc/167/maestros-theater" target="_blank" rel="noreferrer">Maestros Theater</a> · EOC 167</td><td>Land</td><td>Setting</td><td>A performance venue with a crime-family affiliation.</td></tr><tr><td><a href="https://scryfall.com/card/dft/258/night-market" target="_blank" rel="noreferrer">Night Market</a> · DFT 258</td><td>Land</td><td>Setting</td><td>Shopping after dark in a fantasy setting.</td></tr><tr><td><a href="https://scryfall.com/card/tmt/188/northampton-farm" target="_blank" rel="noreferrer">Northampton Farm</a> · TMT 188</td><td>Land</td><td>Setting</td><td>A real-world-style rural retreat from TMNT; useful broader everyday life, not urban New York.</td></tr><tr><td><a href="https://scryfall.com/card/dsc/291/obscura-storefront" target="_blank" rel="noreferrer">Obscura Storefront</a> · DSC 291</td><td>Land</td><td>Setting</td><td>A storefront with an ordinary city-business facade, in a fantasy crime setting.</td></tr><tr><td><a href="https://scryfall.com/card/cmm/1019/port-town" target="_blank" rel="noreferrer">Port Town</a> · CMM 1019</td><td>Land</td><td>Setting</td><td>A coastal settlement rather than a superhero landmark; printing selection matters.</td></tr><tr><td><a href="https://scryfall.com/card/mkm/265/public-thoroughfare" target="_blank" rel="noreferrer">Public Thoroughfare</a> · MKM 265</td><td>Land</td><td>Setting</td><td>A city street; a very useful ordinary infrastructure name.</td></tr><tr><td><a href="https://scryfall.com/card/mkm/266/raucous-theater" target="_blank" rel="noreferrer">Raucous Theater</a> · MKM 266</td><td>Land — Swamp Mountain</td><td>Setting</td><td>A busy entertainment venue in a fantasy city.</td></tr><tr><td><a href="https://scryfall.com/card/mmq/311/rishadan-pawnshop" target="_blank" rel="noreferrer">Rishadan Pawnshop</a> · MMQ 311</td><td>Artifact</td><td>Setting</td><td>An ordinary business in an older fantasy port city.</td></tr><tr><td><a href="https://scryfall.com/card/a25/246/rishadan-port" target="_blank" rel="noreferrer">Rishadan Port</a> · A25 246</td><td>Land</td><td>Setting</td><td>A working harbor; ordinary infrastructure, period-fantasy presentation.</td></tr><tr><td><a href="https://scryfall.com/card/mkm/268/shadowy-backstreet" target="_blank" rel="noreferrer">Shadowy Backstreet</a> · MKM 268</td><td>Land — Plains Swamp</td><td>Setting</td><td>An alley or backstreet in a fantasy city.</td></tr><tr><td><a href="https://scryfall.com/card/snc/256/skybridge-towers" target="_blank" rel="noreferrer">Skybridge Towers</a> · SNC 256</td><td>Land</td><td>Setting</td><td>High-rise architecture and pedestrian infrastructure in New Capenna.</td></tr><tr><td><a href="https://scryfall.com/card/gtc/108/tin-street-market" target="_blank" rel="noreferrer">Tin Street Market</a> · GTC 108</td><td>Enchantment — Aura</td><td>Setting</td><td>A neighborhood market; an Aura rather than a land despite the place name.</td></tr><tr><td><a href="https://scryfall.com/card/snc/258/tramway-station" target="_blank" rel="noreferrer">Tramway Station</a> · SNC 258</td><td>Land</td><td>Setting</td><td>A public-transit stop in New Capenna; among the closest non-Marvel infrastructure matches.</td></tr><tr><td><a href="https://scryfall.com/card/mkm/270/undercity-sewers" target="_blank" rel="noreferrer">Undercity Sewers</a> · MKM 270</td><td>Land — Island Swamp</td><td>Setting</td><td>Urban sewage infrastructure; the Ravnican setting supplies the visual caveat.</td></tr></tbody></table><h2 id="everyday-activities" tabindex="-1">Everyday activities <a class="header-anchor" href="#everyday-activities" aria-label="Permalink to &quot;Everyday activities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Card and printing</th><th>Actual type</th><th>Fit</th><th>Why consider it / qualification</th></tr></thead><tbody><tr><td><a href="https://scryfall.com/card/fdn/160/an-offer-you-cant-refuse" target="_blank" rel="noreferrer">An Offer You Can&#39;t Refuse</a> · FDN 160</td><td>Instant</td><td>Setting</td><td>A familiar organized-crime negotiation; prefer a city-crime printing over alternate art that changes the scene.</td></tr><tr><td><a href="https://scryfall.com/card/clb/217/barroom-brawl" target="_blank" rel="noreferrer">Barroom Brawl</a> · CLB 217</td><td>Sorcery</td><td>Setting</td><td>An ordinary tavern fight, in a fantasy world rather than a modern bar.</td></tr><tr><td><a href="https://scryfall.com/card/9ed/115/blackmail" target="_blank" rel="noreferrer">Blackmail</a> · 9ED 115</td><td>Sorcery</td><td>Setting</td><td>A recognizable crime and social threat; inspect the particular printing&#39;s scene.</td></tr><tr><td><a href="https://scryfall.com/card/snc/135/bouncers-beatdown" target="_blank" rel="noreferrer">Bouncer&#39;s Beatdown</a> · SNC 135</td><td>Instant</td><td>Setting</td><td>A nightclub dispute handled by the bouncer; the New Capenna scene is the qualification.</td></tr><tr><td><a href="https://scryfall.com/card/dsk/170/break-down-the-door" target="_blank" rel="noreferrer">Break Down the Door</a> · DSK 170</td><td>Instant</td><td>Setting</td><td>A mundane act of forced entry in a supernatural-horror setting.</td></tr><tr><td><a href="https://scryfall.com/card/cmm/77/bribery" target="_blank" rel="noreferrer">Bribery</a> · CMM 77</td><td>Sorcery</td><td>Setting</td><td>Corruption and paying someone off; a familiar civic/crime theme with a potentially powerful effect.</td></tr><tr><td><a href="https://scryfall.com/card/rtr/64/destroy-the-evidence" target="_blank" rel="noreferrer">Destroy the Evidence</a> · RTR 64</td><td>Sorcery</td><td>Setting</td><td>An ordinary criminal cover-up, with fantasy-city imagery.</td></tr><tr><td><a href="https://scryfall.com/card/mmq/135/extortion" target="_blank" rel="noreferrer">Extortion</a> · MMQ 135</td><td>Sorcery</td><td>Setting</td><td>An ordinary criminal tactic, with older fantasy-era art.</td></tr><tr><td><a href="https://scryfall.com/card/otj/125/great-train-heist" target="_blank" rel="noreferrer">Great Train Heist</a> · OTJ 125</td><td>Instant</td><td>Setting</td><td>A robbery on public transportation, with a Western-era setting.</td></tr><tr><td><a href="https://scryfall.com/card/tmt/7/grounded-for-life" target="_blank" rel="noreferrer">Grounded for Life</a> · TMT 7</td><td>Instant</td><td>Direct</td><td>A parent&#39;s reprimand and household discipline, delivered in a TMNT scene.</td></tr><tr><td><a href="https://scryfall.com/card/mh2/46/hard-evidence" target="_blank" rel="noreferrer">Hard Evidence</a> · MH2 46</td><td>Sorcery</td><td>Setting</td><td>Evidence gathering with a Crab token: particularly amusing alongside a waterfront or animal theme.</td></tr><tr><td><a href="https://scryfall.com/card/otj/129/highway-robbery" target="_blank" rel="noreferrer">Highway Robbery</a> · OTJ 129</td><td>Sorcery</td><td>Setting</td><td>An ordinary crime transplanted to a frontier setting.</td></tr><tr><td><a href="https://scryfall.com/card/j22/11/hold-for-questioning" target="_blank" rel="noreferrer">Hold for Questioning</a> · J22 11</td><td>Enchantment — Aura</td><td>Setting</td><td>Detaining someone to ask questions, without requiring a superhero premise.</td></tr><tr><td><a href="https://scryfall.com/card/snc/16/hold-for-ransom" target="_blank" rel="noreferrer">Hold for Ransom</a> · SNC 16</td><td>Enchantment — Aura</td><td>Setting</td><td>A mundane crime scenario in New Capenna.</td></tr><tr><td><a href="https://scryfall.com/card/ncc/17/jailbreak" target="_blank" rel="noreferrer">Jailbreak</a> · NCC 17</td><td>Sorcery</td><td>Setting</td><td>Escaping incarceration; New Capenna&#39;s setting is the main caveat.</td></tr><tr><td><a href="https://scryfall.com/card/otj/53/jailbreak-scheme" target="_blank" rel="noreferrer">Jailbreak Scheme</a> · OTJ 53</td><td>Sorcery</td><td>Setting</td><td>Planning a prison escape in a frontier setting.</td></tr><tr><td><a href="https://scryfall.com/card/inr/242/join-the-dance" target="_blank" rel="noreferrer">Join the Dance</a> · INR 242</td><td>Sorcery</td><td>Setting</td><td>A social dance in a Gothic-period setting; an ordinary activity with two Human tokens.</td></tr><tr><td><a href="https://scryfall.com/card/afr/153/kick-in-the-door" target="_blank" rel="noreferrer">Kick in the Door</a> · AFR 153</td><td>Sorcery</td><td>Setting</td><td>An ordinary action with a fantasy-adventuring presentation.</td></tr><tr><td><a href="https://scryfall.com/card/soc/153/land-tax" target="_blank" rel="noreferrer">Land Tax</a> · SOC 153</td><td>Enchantment</td><td>Setting</td><td>Taxes are mundane, even if the printing&#39;s tax collector belongs to another era.</td></tr><tr><td><a href="https://scryfall.com/card/rav/58/mark-of-eviction" target="_blank" rel="noreferrer">Mark of Eviction</a> · RAV 58</td><td>Enchantment — Aura</td><td>Setting</td><td>A painfully ordinary housing problem, presented with Ravnican magical gameplay.</td></tr><tr><td><a href="https://scryfall.com/card/tmc/32/ninja-pizza" target="_blank" rel="noreferrer">Ninja Pizza</a> · TMC 32</td><td>Enchantment</td><td>Direct</td><td>A pizza-business/food theme despite Ninja in the name; mechanically an enchantment that supplies Food.</td></tr><tr><td><a href="https://scryfall.com/card/mkm/30/on-the-job" target="_blank" rel="noreferrer">On the Job</a> · MKM 30</td><td>Instant</td><td>Setting</td><td>People doing their jobs during a fantasy-city investigation.</td></tr><tr><td><a href="https://scryfall.com/card/otj/22/one-last-job" target="_blank" rel="noreferrer">One Last Job</a> · OTJ 22</td><td>Sorcery</td><td>Setting</td><td>The familiar crime-story promise that this is the final job.</td></tr><tr><td><a href="https://scryfall.com/card/mkm/97/outrageous-robbery" target="_blank" rel="noreferrer">Outrageous Robbery</a> · MKM 97</td><td>Instant</td><td>Setting</td><td>A city heist. The act is mundane even if the surrounding setting is fantastic.</td></tr><tr><td><a href="https://scryfall.com/card/otj/62/plan-the-heist" target="_blank" rel="noreferrer">Plan the Heist</a> · OTJ 62</td><td>Sorcery</td><td>Setting</td><td>Planning a robbery, with a frontier rather than modern-city presentation.</td></tr><tr><td><a href="https://scryfall.com/card/snc/154/prizefight" target="_blank" rel="noreferrer">Prizefight</a> · SNC 154</td><td>Instant</td><td>Setting</td><td>A paid fight or boxing match in New Capenna.</td></tr><tr><td><a href="https://scryfall.com/card/m15/195/restock" target="_blank" rel="noreferrer">Restock</a> · M15 195</td><td>Sorcery</td><td>Setting</td><td>Replenishing supplies; inspect the older fantasy printing for what is being restocked.</td></tr><tr><td><a href="https://scryfall.com/card/ltr/29/second-breakfast" target="_blank" rel="noreferrer">Second Breakfast</a> · LTR 29</td><td>Instant</td><td>Setting</td><td>An ordinary extra meal, associated with hobbits rather than modern city residents.</td></tr><tr><td><a href="https://scryfall.com/card/lrw/236/spring-cleaning" target="_blank" rel="noreferrer">Spring Cleaning</a> · LRW 236</td><td>Instant</td><td>Setting</td><td>An ordinary household chore, with a fairy-tale setting and clash mechanics.</td></tr><tr><td><a href="https://scryfall.com/card/stx/34/study-break" target="_blank" rel="noreferrer">Study Break</a> · STX 34</td><td>Instant</td><td>Setting</td><td>Taking a break from schoolwork; the students attend a magical school, but the activity is ordinary.</td></tr><tr><td><a href="https://scryfall.com/card/tmc/128/study-the-classics" target="_blank" rel="noreferrer">Study the Classics</a> · TMC 128</td><td>Sorcery</td><td>Direct</td><td>An ordinary leisure/study joke in a TMNT scene; the exact pictured classics can matter to the packet&#39;s tone.</td></tr><tr><td><a href="https://scryfall.com/card/dgm/19/uncovered-clues" target="_blank" rel="noreferrer">Uncovered Clues</a> · DGM 19</td><td>Sorcery</td><td>Setting</td><td>Investigation and evidence in a fantasy city.</td></tr><tr><td><a href="https://scryfall.com/card/vow/87/wash-away" target="_blank" rel="noreferrer">Wash Away</a> · VOW 87</td><td>Instant</td><td>Setting</td><td>Washing something away is mundane; the Gothic/magical scene is the qualification.</td></tr><tr><td><a href="https://scryfall.com/card/pip/88/well-rested" target="_blank" rel="noreferrer">Well Rested</a> · PIP 88</td><td>Enchantment — Aura</td><td>Direct</td><td>Getting a good rest, with Fallout branding and a post-apocalyptic setting to consider.</td></tr><tr><td><a href="https://scryfall.com/card/clb/211/youve-been-caught-stealing" target="_blank" rel="noreferrer">You&#39;ve Been Caught Stealing</a> · CLB 211</td><td>Sorcery</td><td>Setting</td><td>An ordinary crime consequence in a Dungeons &amp; Dragons setting; retains its full normal modes.</td></tr></tbody></table>',8)])])}const y=r(n,[["render",i]]);export{g as __pageData,y as default};
